namespace notebook;
table Measurement { source:double; result:double; }
table Outputs { value:Measurement (required); }
root_type Outputs;

{ pkgs, inputs, params }:
{
  run = ''
    jq '{value: {source: .measurement, result: (.measurement * .factor)}}' \
      <<< "$TSUGUMI_PARAMS_JSON" > "$TSUGUMI_OUTPUT"
  '';
}

"""Visualize a measurement and the value computed by the upstream Card."""
import marimo

app = marimo.App()


@app.cell
def configuration():
    source = 4.0
    result = 8.0
    return source, result


@app.cell
def explanation(result):
    import marimo as mo
    mo.md(f"## Notebook result\n\nThe selected result is **{result:g}**.")
    return mo,


@app.cell
def figure(source, result):
    import matplotlib.pyplot as plt
    fig, ax = plt.subplots()
    ax.bar(["Input", "Result"], [source, result])
    ax.set_title("Measurement and scaled value")
    fig
    return fig, ax, plt


if __name__ == "__main__":
    app.run()

attribute "tsugumi";
namespace notebook;
table Number { value:double; }
table Files { value:string; }
table Outputs { value:Number (required); report:Files (required, tsugumi: "directory"); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.marimo ps.matplotlib ];
    fonts = [ pkgs.ipaexfont ];
  };
}

{ pkgs, inputs, params }:
{
  run = ''
    set -e
    if [[ ! -r "$JSON_IN" ]]; then
      printf '%s\n' 'Missing input: in' >&2
      exit 1
    fi

    cat "$JSON_IN"

    # Keep the Canvas preview below the worker frame limit. jq slices at
    # Unicode character boundaries; stdout still receives the full value.
    preview='def preview: if utf8bytelength > 1048576 then
      .[0:((1048576 - 64) / 4)] + "\n\n[Display truncated.]"
      else . end;'
    case ${pkgs.lib.escapeShellArg params.format} in
      text)
        jq -Rs "$preview"' {text: preview}' "$JSON_IN" > "$TSUGUMI_DISPLAY"
        ;;
      markdown)
        jq -es --arg field ${pkgs.lib.escapeShellArg params.markdown_field} "$preview"'
          if length == 1 and (.[0] | type == "object" and (.[$field] | type == "string"))
          then (.[0][$field] |
            if contains("\u0000") then error("Markdown input contains a NUL character")
            else {markdown: preview}
            end)
          else error("Markdown input must contain the string field " + $field)
          end
        ' "$JSON_IN" > "$TSUGUMI_DISPLAY"
        ;;
      *)
        printf '%s\n' 'Unknown display format: expected text or markdown' >&2
        exit 1
        ;;
    esac
  '';
}
